```python
from __future__ import annotations

from collections.abc import Iterable, Sequence
import math
import numpy as np


def pass_at_n(p: float, n: int) -> float:
    p = float(p)
    if not math.isfinite(p) or not 0.0 <= p <= 1.0:
        raise ValueError("p must lie in [0, 1]")
    if isinstance(n, bool) or int(n) != n or int(n) <= 0:
        raise ValueError("n must be a positive integer")
    n = int(n)
    if p == 0.0:
        return 0.0
    if p == 1.0:
        return 1.0
    return float(-np.expm1(n * np.log1p(-p)))


def aggregate_pass_curve(ps: Sequence[float], budgets: Iterable[int]) -> np.ndarray:
    probabilities = np.asarray(ps, dtype=np.float64)
    budgets = list(budgets)
    if probabilities.ndim != 1 or probabilities.size == 0:
        raise ValueError("ps must be non-empty")
    if not np.isfinite(probabilities).all() or np.any((probabilities < 0) | (probabilities > 1)):
        raise ValueError("every probability must lie in [0, 1]")
    if not budgets:
        raise ValueError("budgets must be non-empty")
    return np.asarray(
        [np.mean([pass_at_n(float(p), int(n)) for p in probabilities]) for n in budgets],
        dtype=np.float64,
    )
```

`log1p` и `expm1` уменьшают потерю точности, когда $p$ мал, а $N$ велик.

```python
from __future__ import annotations

from collections.abc import Sequence
import numpy as np


def process_score(step_scores: Sequence[float], method: str) -> float:
    values = np.asarray(step_scores, dtype=np.float64)
    if values.ndim != 1 or values.size == 0:
        raise ValueError("step_scores must be non-empty")
    if not np.isfinite(values).all() or np.any((values < 0) | (values > 1)):
        raise ValueError("step scores must lie in [0, 1]")
    method = method.lower()
    if method == "min":
        return float(values.min())
    if method == "mean":
        return float(values.mean())
    if method == "product":
        return float(values.prod())
    if method == "last":
        return float(values[-1])
    if method == "log_product":
        if np.any(values == 0):
            return float("-inf")
        return float(np.log(values).sum())
    raise ValueError("unknown aggregation method")
```

Логарифм произведения численно устойчивее для длинных цепочек. Он не исправляет семантическую проблему: перемножать оценки можно осмысленно лишь при подходящей вероятностной интерпретации.
